              <div className="md:col-span-2"><label className="block text-sm font-bold text-gray-700 mb-2">متن کپی‌رایت فوتر</label><input className="w-full px-4 py-3 rounded-xl border border-gray-300 focus:ring-2 focus:ring-indigo-500 outline-none transition-shadow" value={generalData.footerText} onChange={(e) => handleGeneralChange('footerText', e.target.value)} /></div>
           </div>
           <div className="flex items-center justify-end border-t border-gray-100 pt-6"><button onClick={saveSettings} disabled={isSaving} className="px-8 py-3 bg-indigo-600 text-white rounded-xl font-bold shadow-lg shadow-indigo-200 hover:bg-indigo-700">{isSaving ? 'در حال ذخیره...' : 'ذخیره تغییرات'}</button></div>
        </div>
      )}

      {activeTab === 'businesses' && (<div className="space-y-6">... businesses logic ...</div>)}
      {activeTab === 'google_forms' && (<div className="space-y-6">... google logic ...</div>)}
